  [inst_2 : Fintype.{u_3} r] {A : Matrix.{u_1, u_1, 0} m m Complex} {B : Matrix.{u_1, u_2, 0} m n Complex}
  {C : Matrix.{u_2, u_2, 0} n n Complex} (X : Matrix.{u_3, u_1, 0} r m Complex) (Y : Matrix.{u_3, u_2, 0} r n Complex),
  Eq.{u_1 + 1} A (HMul.hMul.{max u_1 u_3, max u_1 u_3, u_1} (Matrix.conjTranspose.{0, u_3, u_1} X) X) →
    Eq.{max (u_1 + 1) (u_2 + 1)} B
        (HMul.hMul.{max u_1 u_3, max u_2 u_3, max u_1 u_2} (Matrix.conjTranspose.{0, u_3, u_1} X) Y) →
      Eq.{u_2 + 1} C (HMul.hMul.{max u_2 u_3, max u_2 u_3, u_2} (Matrix.conjTranspose.{0, u_3, u_2} Y) Y) →
        Eq.{1}
          (HSub.hSub.{0, 0, 0}
            (HAdd.hAdd.{0, 0, 0} (PositiveBlocks.hsSq.{u_1, u_1} A) (PositiveBlocks.hsSq.{u_2, u_2} C))
            (HMul.hMul.{0, 0, 0} 2 (PositiveBlocks.hsSq.{u_1, u_2} B)))
          (PositiveBlocks.hsSq.{u_3, u_3}
            (HSub.hSub.{u_3, u_3, u_3}
              (HMul.hMul.{max u_1 u_3, max u_1 u_3, u_3} X (Matrix.conjTranspose.{0, u_3, u_1} X))
              (HMul.hMul.{max u_2 u_3, max u_2 u_3, u_3} Y (Matrix.conjTranspose.{0, u_3, u_2} Y))))

