              (HPow.hPow.{0, 0, 0} (PositiveBlocks.hsNorm.{u_2, u_2} C) 2))
            (HMul.hMul.{0, 0, 0} 2 (HPow.hPow.{0, 0, 0} (PositiveBlocks.hsNorm.{u_1, u_2} B) 2)))
          (HPow.hPow.{0, 0, 0}
            (PositiveBlocks.hsNorm.{u_3, u_3}
              (HSub.hSub.{u_3, u_3, u_3}
                (HMul.hMul.{max u_1 u_3, max u_1 u_3, u_3} X (Matrix.conjTranspose.{0, u_3, u_1} X))
